"""Add Veqrya/Supabase session auth while preserving legacy HOME_TOKEN fallback."""
from pathlib import Path
import re
import sys

worker = Path(sys.argv[1] if len(sys.argv) > 1 else "src/luis-home-app/app/src/main/java/com/luis/home/WorkerSync.java")
main = Path(sys.argv[2] if len(sys.argv) > 2 else "src/luis-home-app/app/src/main/java/com/luis/home/MainActivity.java")

s = worker.read_text()

anchor = '    private static final String LEARNING_LATEST = "https://skgmgxthymnzubbobqxu.supabase.co/functions/v1/home-learning-latest";\n'
insert = anchor + '    private static final String VEQRYA_MOBILE_API = "https://skgmgxthymnzubbobqxu.supabase.co/functions/v1/veqrya-mobile-api";\n    private static final String SUPABASE_FUNCTIONS = "https://skgmgxthymnzubbobqxu.supabase.co/functions/v1/";\n'
if anchor not in s:
    raise SystemExit("WorkerSync constants anchor not found")
s = s.replace(anchor, insert, 1)

anchor = '    private final Context context;\n    private final File outboxFile;\n'
insert = '    private final Context context;\n    private final File outboxFile;\n    private final VeqryaSession veqrya;\n'
if anchor not in s:
    raise SystemExit("WorkerSync field anchor not found")
s = s.replace(anchor, insert, 1)

anchor = '        this.context = context.getApplicationContext();\n        this.outboxFile = new File(this.context.getNoBackupFilesDir(), "home-private-outbox.json");\n'
insert = anchor + '        this.veqrya = new VeqryaSession(this.context);\n'
if anchor not in s:
    raise SystemExit("WorkerSync constructor anchor not found")
s = s.replace(anchor, insert, 1)

old = '''    boolean isConfigured() {\n        return readToken() != null;\n    }\n'''
new = '''    boolean hasVeqryaSession() { return veqrya.isConfigured(); }\n\n    boolean isConfigured() {\n        return veqrya.isConfigured() || readToken() != null;\n    }\n\n    String authMode() {\n        if (veqrya.isConfigured()) return "veqrya";\n        return readToken() != null ? "legacy-home-token" : "none";\n    }\n\n    void signInVeqrya(String email, String password) throws Exception {\n        veqrya.signIn(email, password);\n        context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE).edit()\n            .putString("lastError", "").apply();\n    }\n\n    boolean signUpVeqrya(String email, String password) throws Exception {\n        boolean signedIn=veqrya.signUp(email,password);\n        if(signedIn) context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE).edit()\n            .putString("lastError", "").apply();\n        return signedIn;\n    }\n\n    void clearAuth() {\n        veqrya.clear();\n        clearToken();\n    }\n'''
if old not in s:
    raise SystemExit("WorkerSync configured anchor not found")
s = s.replace(old, new, 1)

pattern = re.compile(r'''    private String request\(String method, String path, JSONObject body, int readTimeoutMs\) throws Exception \{.*?\n    private String readAll\(InputStream in\) throws Exception \{''', re.S)
replacement = '''    private boolean mobileApiSupports(String path) {\n        return "/api/snapshot".equals(path) || "/api/tasks".equals(path)\n            || path.startsWith("/api/tasks/") || "/api/cards".equals(path)\n            || "/api/attempts".equals(path) || "/api/activity".equals(path);\n    }\n\n    private String request(String method, String path, JSONObject body, int readTimeoutMs) throws Exception {\n        if (veqrya.isConfigured() && mobileApiSupports(path))\n            return requestAbsolute(method, VEQRYA_MOBILE_API + path, body, readTimeoutMs);\n        return requestAbsolute(method, API + path, body, readTimeoutMs);\n    }\n\n    private String requestAbsolute(String method, String url, JSONObject body, int readTimeoutMs) throws Exception {\n        boolean supabaseFunction = url.startsWith(SUPABASE_FUNCTIONS);\n        boolean sessionRoute = veqrya.isConfigured() && supabaseFunction;\n        String token = sessionRoute ? veqrya.accessToken() : readToken();\n        if (token == null) {\n            if (veqrya.isConfigured())\n                throw new IllegalStateException("This feature still needs legacy HOME Sync.");\n            throw new IllegalStateException("Connect HOME Sync or sign in to Veqrya first.");\n        }\n        try {\n            return requestAbsoluteOnce(method,url,body,readTimeoutMs,token,sessionRoute,supabaseFunction);\n        } catch (IllegalStateException first) {\n            if (!sessionRoute || first.getMessage()==null || !first.getMessage().contains("HTTP 401")) throw first;\n            String refreshed=veqrya.refreshAccessToken();\n            return requestAbsoluteOnce(method,url,body,readTimeoutMs,refreshed,true,supabaseFunction);\n        }\n    }\n\n    private String requestAbsoluteOnce(String method, String url, JSONObject body, int readTimeoutMs,\n                                       String token, boolean sessionRoute, boolean supabaseFunction) throws Exception {\n        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();\n        try {\n            connection.setRequestMethod(method);\n            connection.setConnectTimeout(10000);\n            connection.setReadTimeout(Math.max(5000, readTimeoutMs));\n            if (sessionRoute) {\n                connection.setRequestProperty("Authorization", "Bearer " + token);\n                connection.setRequestProperty("apikey", VeqryaSession.PUBLISHABLE_KEY);\n            } else if (supabaseFunction) {\n                connection.setRequestProperty("X-HOME-Authorization", "Bearer " + token);\n            } else {\n                connection.setRequestProperty("Authorization", "Bearer " + token);\n            }\n            connection.setRequestProperty("Content-Type", "application/json; charset=utf-8");\n            connection.setRequestProperty("Accept", "application/json");\n            connection.setRequestProperty("Cache-Control", "no-cache");\n\n            if (body != null) {\n                connection.setDoOutput(true);\n                try (OutputStream out = connection.getOutputStream()) {\n                    out.write(body.toString().getBytes(StandardCharsets.UTF_8));\n                }\n            }\n\n            int status = connection.getResponseCode();\n            InputStream stream = status >= 200 && status < 300\n                    ? connection.getInputStream()\n                    : connection.getErrorStream();\n            String payload = stream == null ? "" : readAll(stream);\n\n            if (status == 401) {\n                if (sessionRoute) throw new IllegalStateException("Veqrya session rejected (HTTP 401).");\n                throw new IllegalStateException("HOME token rejected. Reconnect HOME Sync.");\n            }\n            if (status < 200 || status >= 300) {\n                String message = "HOME Sync failed (HTTP " + status + ")";\n                try {\n                    String server = new JSONObject(payload).optString("error", "");\n                    if (!server.isEmpty()) message += ": " + server;\n                } catch (Exception ignored) { }\n                throw new IllegalStateException(message);\n            }\n            return payload;\n        } finally {\n            connection.disconnect();\n        }\n    }\n\n    private String readAll(InputStream in) throws Exception {'''
s, count = pattern.subn(replacement, s, count=1)
if count != 1:
    raise SystemExit("WorkerSync request block anchor not found")

needle = 'out.put("configured",isConfigured()).put("pending",user).put("pendingUser",user)'
replace = 'out.put("configured",isConfigured()).put("authMode",authMode()).put("pending",user).put("pendingUser",user)'
if needle not in s:
    raise SystemExit("WorkerSync status anchor not found; run after patch_worker_sync_v18.py")
s = s.replace(needle, replace, 1)

worker.write_text(s)

m = main.read_text()
anchor = '''        @JavascriptInterface\n        public void configureNotion() {\n'''
veqrya_method = '''        @JavascriptInterface\n        public boolean hasVeqryaSession() { return worker.hasVeqryaSession(); }\n\n        @JavascriptInterface\n        public void configureVeqrya() {\n            runOnUiThread(() -> {\n                EditText email = new EditText(MainActivity.this);\n                email.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);\n                email.setSingleLine(true);\n                email.setHint("Email");\n                AlertDialog emailDialog = new AlertDialog.Builder(MainActivity.this)\n                        .setTitle("Connect Veqrya")\n                        .setMessage("Sign in or create an account. Credentials go directly to Supabase Auth and are never stored in the WebView.")\n                        .setView(email)\n                        .setNegativeButton("Cancel", null)\n                        .setPositiveButton("Next", null)\n                        .create();\n                emailDialog.setOnShowListener(ignored -> emailDialog.getButton(AlertDialog.BUTTON_POSITIVE)\n                        .setOnClickListener(button -> {\n                            String address=email.getText().toString().trim();\n                            if(address.isEmpty()||!address.contains("@")){email.setError("Enter your Veqrya email.");return;}\n                            EditText password = new EditText(MainActivity.this);\n                            password.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n                            password.setSingleLine(true);\n                            password.setHint("Password");\n                            AlertDialog passwordDialog = new AlertDialog.Builder(MainActivity.this)\n                                    .setTitle("Veqrya password")\n                                    .setMessage("Passwords are used only for authentication and are never saved.")\n                                    .setView(password)\n                                    .setNegativeButton("Cancel", null)\n                                    .setNeutralButton("Create account", null)\n                                    .setPositiveButton("Sign in", null)\n                                    .create();\n                            passwordDialog.setOnShowListener(x -> {\n                                final android.widget.Button signIn=passwordDialog.getButton(AlertDialog.BUTTON_POSITIVE);\n                                final android.widget.Button create=passwordDialog.getButton(AlertDialog.BUTTON_NEUTRAL);\n                                signIn.setOnClickListener(v -> {\n                                    String secret=password.getText().toString();\n                                    if(secret.length()<6){password.setError("Use at least 6 characters.");return;}\n                                    signIn.setEnabled(false);create.setEnabled(false);\n                                    syncQueue.execute(() -> {\n                                        try {\n                                            worker.signInVeqrya(address,secret);\n                                            runOnUiThread(() -> {\n                                                passwordDialog.dismiss();emailDialog.dismiss();syncReady=false;\n                                                callback("onNotionConnected", new JSONObject());\n                                                scheduleTodoStateSync();\n                                            });\n                                        } catch(Exception ex) {\n                                            runOnUiThread(() -> {\n                                                signIn.setEnabled(true);create.setEnabled(true);password.setText("");\n                                                password.setError(ex.getMessage()==null?"Sign-in failed.":ex.getMessage());\n                                            });\n                                        }\n                                    });\n                                });\n                                create.setOnClickListener(v -> {\n                                    String secret=password.getText().toString();\n                                    if(secret.length()<6){password.setError("Use at least 6 characters.");return;}\n                                    signIn.setEnabled(false);create.setEnabled(false);\n                                    syncQueue.execute(() -> {\n                                        try {\n                                            boolean signedIn=worker.signUpVeqrya(address,secret);\n                                            runOnUiThread(() -> {\n                                                signIn.setEnabled(true);create.setEnabled(true);password.setText("");\n                                                if(signedIn){\n                                                    passwordDialog.dismiss();emailDialog.dismiss();syncReady=false;\n                                                    callback("onNotionConnected", new JSONObject());scheduleTodoStateSync();\n                                                } else password.setError("Account created. Confirm your email, then sign in.");\n                                            });\n                                        } catch(Exception ex) {\n                                            runOnUiThread(() -> {\n                                                signIn.setEnabled(true);create.setEnabled(true);password.setText("");\n                                                password.setError(ex.getMessage()==null?"Account creation failed.":ex.getMessage());\n                                            });\n                                        }\n                                    });\n                                });\n                            });\n                            passwordDialog.show();\n                        }));\n                emailDialog.show();\n            });\n        }\n\n'''
if anchor not in m:
    raise SystemExit("MainActivity configureNotion anchor not found")
m = m.replace(anchor, veqrya_method + anchor, 1)

if '            worker.clearToken();\n' not in m:
    raise SystemExit("MainActivity disconnect anchor not found")
m = m.replace('            worker.clearToken();\n', '            worker.clearAuth();\n', 1)
main.write_text(m)

print(f"Patched {worker} and {main}: Veqrya session auth/signup + legacy fallback")
